select t0.DocEntry, t4.DistNumber, t3.Quantity,t1.FromWhsCod, t1.WhsCode,Dateadd(minute, cast(right(RIGHT('0000' +cast(t2.CreateTime as varchar(4)), 4),2) as int),Dateadd(hour, cast(left(RIGHT('0000' +cast(t2.CreateTime as varchar(4)), 4),2) as int),t2.CreateDate)) [CreateDate]from OWTR t0 inner join WTR1 t1 on t0.DocEntry = t1.DocEntryinner join OITL t2 on t0.DocEntry = t2.DocEntry and t2.DocType = t0.ObjType and t2.DocLine = t1.LineNuminner join ITL1 t3 on t2.LogEntry = t3.LogEntryinner join OBTN t4 on t3.ItemCode = t4.ItemCode and t3.SysNumber = t4.SysNumberinner join BEAS_QSFTHAUPT t5 on t1.U_beas_basetype = 'QC' and t1.DocEntry = t5.DocEntryand t4.AbsEntry = t3.MdAbsEntrywhere t3.Quantity > 0 and t2.CreateDate >= [%0] and t2.CreateDate <= [%1]order by DocEntry desc